import React from 'react';
import { Link } from 'react-router-dom';

function Header(props) {
    return (
        <div style={{ backgroundColor: 'blue' }}>
            <h3>Header</h3>
            <Link
                to="/page1"
                style={{
                    background: 'blue',
                    color: 'white',
                    padding: '5px 10px',
                    textDecoration: 'none'
                }}
            >
                Page 1
            </Link>
        </div>
    );
}

export default Header;
